import React, { useState, useMemo, useRef, useEffect } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useData } from '../hooks/useDataContext';
import { useToast } from '../hooks/useToast';
import { useAuth } from '../hooks/useAuth';
import { Table, SortConfig } from '../components/common/Table';
import { Button } from '../components/common/Button';
import { Modal } from '../components/common/Modal';
import { ICONS } from '../constants';
import { PersonStatus, Student, UserRole, Class } from '../types';
import { ConfirmationModal } from '../components/common/ConfirmationModal';
import { Pagination } from '../components/common/Pagination';
import { ResetPasswordModal } from '../components/auth/ChangePasswordModal';
import { PaymentModal } from '../components/finance/PaymentModal';


const removeAccents = (str: string) => {
  if (!str) return '';
  return str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d").replace(/Đ/g, "D");
};

const ClassSelector: React.FC<{
    allClasses: Class[];
    selectedClassIds: string[];
    onChange: (selectedIds: string[]) => void;
}> = ({ allClasses, selectedClassIds, onChange }) => {
    const [searchTerm, setSearchTerm] = useState('');

    const filteredClasses = useMemo(() => {
        return allClasses.filter(cls =>
            cls.name.toLowerCase().includes(searchTerm.toLowerCase())
        );
    }, [allClasses, searchTerm]);

    const handleToggle = (classId: string) => {
        const newSelectedIds = selectedClassIds.includes(classId)
            ? selectedClassIds.filter(id => id !== classId)
            : [...selectedClassIds, classId];
        onChange(newSelectedIds);
    };

    return (
        <div className="border rounded-md dark:border-gray-600 bg-white dark:bg-gray-800">
            <div className="p-2 border-b dark:border-gray-600">
                <input
                    type="text"
                    placeholder="Tìm kiếm lớp học..."
                    value={searchTerm}
                    onChange={e => setSearchTerm(e.target.value)}
                    className="form-input w-full p-2"
                />
            </div>
            <div className="max-h-60 overflow-y-auto p-2">
                {filteredClasses.length > 0 ? (
                    filteredClasses.map(cls => (
                        <label key={cls.id} className="flex items-center p-2 rounded-md hover:bg-gray-100 dark:hover:bg-gray-700 cursor-pointer">
                            <input
                                type="checkbox"
                                checked={selectedClassIds.includes(cls.id)}
                                onChange={() => handleToggle(cls.id)}
                                className="h-4 w-4 rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                            />
                            <span className="ml-3 text-sm">{cls.name}</span>
                        </label>
                    ))
                ) : (
                    <p className="text-center text-sm text-gray-500 p-4">Không tìm thấy lớp học.</p>
                )}
            </div>
             <div className="p-2 border-t dark:border-gray-600 text-sm text-gray-500 dark:text-gray-400">
                Đã chọn: {selectedClassIds.length} lớp học
            </div>
        </div>
    );
};


const StudentForm: React.FC<{ 
    student?: Student; 
    onSubmit: (payload: { student: Student, classIds: string[] }) => void; 
    onCancel: () => void;
    allClasses: Class[];
    generatedId?: string;
}> = ({ student, onSubmit, onCancel, allClasses, generatedId }) => {
    const [formData, setFormData] = useState<Partial<Student>>({
        id: generatedId || '',
        name: '',
        email: generatedId ? `${generatedId}@thaydat.edu.vn` : '',
        phone: '',
        address: '',
        dob: '',
        parentName: '',
        status: PersonStatus.ACTIVE,
        createdAt: '',
        balance: 0,
        password: '',
        ...student,
    });
    const [selectedClassIds, setSelectedClassIds] = useState<string[]>([]);
    const [errors, setErrors] = useState<Partial<Record<keyof Student, string>>>({});
    const idInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        idInputRef.current?.focus();
        if (student) {
            const enrolledClassIds = allClasses
                .filter(c => c.studentIds.includes(student.id))
                .map(c => c.id);
            setSelectedClassIds(enrolledClassIds);
        }
    }, [student, allClasses]);

    const validate = () => {
        const newErrors: Partial<Record<keyof Student, string>> = {};
        if (!formData.id?.trim()) newErrors.id = "Mã học viên là bắt buộc.";
        if (!formData.name?.trim()) newErrors.name = "Họ tên là bắt buộc.";
        if (!formData.email?.trim()) {
            newErrors.email = "Email là bắt buộc.";
        } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
            newErrors.email = "Email không hợp lệ.";
        }
        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };


    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => {
            const newData = { ...prev, [name]: value };

            // Auto-update email when ID changes, if email matches the pattern of the old ID
            if (name === 'id') {
                const prevId = prev.id || '';
                const currentEmail = prev.email || '';
                const defaultDomain = '@thaydat.edu.vn';

                // If email is empty OR exactly matches [prevId]@thaydat.edu.vn
                if (!currentEmail || currentEmail === `${prevId}${defaultDomain}`) {
                    newData.email = `${value}${defaultDomain}`;
                }
            }

            return newData;
        });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (validate()) {
            const studentData = { ...formData };
            if (!studentData.password) {
                delete studentData.password;
            }
            onSubmit({ student: studentData as Student, classIds: selectedClassIds });
        }
    };

    const inputGroupClass = "grid grid-cols-1 md:grid-cols-2 gap-4";

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            <fieldset className="form-fieldset">
                <legend className="form-legend">Thông tin cá nhân</legend>
                <div className={`${inputGroupClass} mt-2`}>
                    <div>
                        <label className="block text-sm font-medium">Mã Học viên <span className="text-red-500">*</span></label>
                        <input ref={idInputRef} type="text" name="id" value={formData.id} onChange={handleChange} className="form-input mt-1" />
                        {errors.id && <p className="text-red-500 text-xs mt-1">{errors.id}</p>}
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Họ tên <span className="text-red-500">*</span></label>
                        <input type="text" name="name" value={formData.name} onChange={handleChange} className="form-input mt-1" />
                        {errors.name && <p className="text-red-500 text-xs mt-1">{errors.name}</p>}
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Ngày sinh</label>
                        <input type="date" name="dob" value={formData.dob} onChange={handleChange} className="form-input mt-1" />
                    </div>
                     <div>
                        <label className="block text-sm font-medium">Trạng thái</label>
                        <select name="status" value={formData.status} onChange={handleChange} className="form-select mt-1">
                            <option value={PersonStatus.ACTIVE}>Hoạt động</option>
                            <option value={PersonStatus.INACTIVE}>Tạm nghỉ</option>
                        </select>
                    </div>
                </div>
            </fieldset>

             <fieldset className="form-fieldset">
                <legend className="form-legend">Thông tin liên lạc & Tài khoản</legend>
                 <div className={`${inputGroupClass} mt-2`}>
                    <div>
                        <label className="block text-sm font-medium">Email <span className="text-red-500">*</span></label>
                        <input type="email" name="email" value={formData.email} onChange={handleChange} className="form-input mt-1" />
                        {errors.email && <p className="text-red-500 text-xs mt-1">{errors.email}</p>}
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Số điện thoại</label>
                        <input type="tel" name="phone" value={formData.phone} onChange={handleChange} className="form-input mt-1" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Tên phụ huynh</label>
                        <input type="text" name="parentName" value={formData.parentName} onChange={handleChange} className="form-input mt-1" />
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Mật khẩu</label>
                        <input type="password" name="password" value={formData.password || ''} onChange={handleChange} className="form-input mt-1" placeholder="Bỏ trống để dùng ngày sinh (ddmmyyyy)" />
                    </div>
                </div>
                 <div className="mt-4">
                    <label className="block text-sm font-medium">Địa chỉ</label>
                    <input type="text" name="address" value={formData.address} onChange={handleChange} className="form-input mt-1" />
                </div>
            </fieldset>

            <fieldset className="form-fieldset">
                <legend className="form-legend">Ghi danh Lớp học</legend>
                 <ClassSelector
                    allClasses={allClasses}
                    selectedClassIds={selectedClassIds}
                    onChange={setSelectedClassIds}
                />
            </fieldset>

            <div className="flex justify-end space-x-4 pt-4 border-t dark:border-gray-700">
                <Button type="button" variant="secondary" onClick={onCancel}>Hủy</Button>
                <Button type="submit">{student ? 'Lưu thay đổi' : 'Thêm học viên'}</Button>
            </div>
        </form>
    );
};


export const StudentsScreen: React.FC = () => {
    const { state, addStudent, updateStudent, deleteStudent } = useData();
    const { role } = useAuth();
    const { toast } = useToast();
    const location = useLocation();
    const navigate = useNavigate();
    const [isModalOpen, setModalOpen] = useState(false);
    const [editingStudent, setEditingStudent] = useState<Student | undefined>(undefined);
    const [confirmModalState, setConfirmModalState] = useState<{ isOpen: boolean; student: Student | null }>({ isOpen: false, student: null });
    const [resetPasswordModalState, setResetPasswordModalState] = useState<{ isOpen: boolean; student: Student | null }>({ isOpen: false, student: null });
    const [paymentModalState, setPaymentModalState] = useState<{ isOpen: boolean; student: Student | null }>({ isOpen: false, student: null });
    const [searchQuery, setSearchQuery] = useState('');
    const [classFilter, setClassFilter] = useState('all');
    const [currentPage, setCurrentPage] = useState(1);
    const [sortConfig, setSortConfig] = useState<SortConfig<Student> | null>({ key: 'name', direction: 'ascending' });
    const ITEMS_PER_PAGE = 10;

    const canManage = role === UserRole.ADMIN || role === UserRole.MANAGER;

    const handleSort = (key: keyof Student) => {
        let direction: 'ascending' | 'descending' = 'ascending';
        if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
            direction = 'descending';
        }
        setSortConfig({ key, direction });
    };

    const handleOpenModal = (student?: Student) => {
        setEditingStudent(student);
        setModalOpen(true);
    };

    const generatedStudentId = useMemo(() => {
        let maxId = 0;
        const regex = /^HS(\d+)$/i;
        state.students.forEach(s => {
            const match = s.id.match(regex);
            if (match) {
                const num = parseInt(match[1], 10);
                if (num > maxId) maxId = num;
            }
        });
        return `HS${String(maxId + 1).padStart(3, '0')}`;
    }, [state.students]);

    useEffect(() => {
        const { editStudentId } = location.state || {};
        if (editStudentId && !isModalOpen) {
            const studentToEdit = state.students.find(s => s.id === editStudentId);
            if (studentToEdit) {
                handleOpenModal(studentToEdit);
            }
        }
    }, [location.state, state.students, isModalOpen]);

    const filteredStudents = useMemo(() => {
        let studentsToFilter = state.students;

        if (classFilter !== 'all') {
            const selectedClass = state.classes.find(c => c.id === classFilter);
            if (selectedClass) {
                const studentIdsInClass = new Set(selectedClass.studentIds);
                studentsToFilter = studentsToFilter.filter(s => studentIdsInClass.has(s.id));
            }
        }

        if (!searchQuery) return studentsToFilter;

        const normalizedQuery = removeAccents(searchQuery.toLowerCase());
        return studentsToFilter.filter(s => {
            const normalizedName = removeAccents(s.name.toLowerCase());
            const phoneMatch = s.phone.includes(searchQuery);
            const nameMatch = normalizedName.includes(normalizedQuery);
            return phoneMatch || nameMatch;
        });
    }, [state.students, state.classes, searchQuery, classFilter]);

    const sortedStudents = useMemo(() => {
        let sortableItems = [...filteredStudents];

        if (searchQuery) {
            const normalizedQuery = removeAccents(searchQuery.toLowerCase());

            const getScore = (student: Student) => {
                // Phone match is highest priority
                if (student.phone.includes(searchQuery)) {
                    return 3;
                }

                const normalizedName = removeAccents(student.name.toLowerCase());
                const nameParts = normalizedName.split(' ');
                const lastName = nameParts[nameParts.length - 1];

                // Last name match is second priority
                if (lastName.startsWith(normalizedQuery)) {
                    return 2;
                }

                // Any other name match is lowest priority
                if (normalizedName.includes(normalizedQuery)) {
                    return 1;
                }

                return 0;
            };

            sortableItems.sort((a, b) => {
                const scoreA = getScore(a);
                const scoreB = getScore(b);

                if (scoreA !== scoreB) {
                    return scoreB - scoreA; // Higher score comes first
                }

                // If scores are equal, sort by name alphabetically
                return a.name.localeCompare(b.name, 'vi');
            });

        } else if (sortConfig !== null) {
            // Original sorting logic when not searching
            const getLastName = (fullName: string) => {
                if (!fullName) return '';
                const parts = fullName.trim().split(/\s+/);
                return parts[parts.length - 1];
            };

            sortableItems.sort((a, b) => {
                if (sortConfig.key === 'name') {
                    const lastNameA = getLastName(a.name);
                    const lastNameB = getLastName(b.name);

                    const lastNameComparison = lastNameA.localeCompare(lastNameB, 'vi');

                    if (lastNameComparison !== 0) {
                        return sortConfig.direction === 'ascending' ? lastNameComparison : -lastNameComparison;
                    }

                    // If last names are the same, sort by full name for stability
                    const fullNameComparison = a.name.localeCompare(b.name, 'vi');
                    return sortConfig.direction === 'ascending' ? fullNameComparison : -fullNameComparison;
                }

                // Fallback for other columns
                const aValue = a[sortConfig.key];
                const bValue = b[sortConfig.key];

                if (aValue == null || bValue == null) return 0;

                if (aValue < bValue) return sortConfig.direction === 'ascending' ? -1 : 1;
                if (aValue > bValue) return sortConfig.direction === 'ascending' ? 1 : -1;
                return 0;
            });
        }
        return sortableItems;
    }, [filteredStudents, sortConfig, searchQuery]);

    const totalPages = Math.ceil(sortedStudents.length / ITEMS_PER_PAGE);
    const paginatedStudents = sortedStudents.slice(
        (currentPage - 1) * ITEMS_PER_PAGE,
        currentPage * ITEMS_PER_PAGE
    );

    useEffect(() => {
        setCurrentPage(1);
    }, [searchQuery, classFilter, sortConfig]);


    const columns = [
        { header: 'Mã HV', accessor: 'id' as keyof Student, sortable: true },
        { 
            header: 'Họ tên', 
            accessor: (item: Student) => (
                <Link to={`/student/${item.id}`} className="text-primary dark:text-indigo-400 hover:underline font-semibold">
                    {item.name}
                </Link>
            ),
            sortable: true,
            sortKey: 'name' as keyof Student,
        },
        { header: 'Số điện thoại', accessor: 'phone' as keyof Student },
        { 
            header: 'Số dư', 
            accessor: (item: Student) => {
                const balanceText = (
                    <span className={`font-semibold ${item.balance < 0 ? 'text-red-600 dark:text-red-400' : 'text-green-600 dark:text-green-400'}`}>
                        {item.balance.toLocaleString('vi-VN')} ₫
                    </span>
                );

                if (role === UserRole.VIEWER || item.balance >= 0) {
                    return balanceText;
                }

                return (
                    <button 
                        onClick={() => setPaymentModalState({ isOpen: true, student: item })}
                        className="font-semibold text-red-600 dark:text-red-400 hover:text-red-800 dark:hover:text-red-300 hover:underline"
                        title="Ghi nhận thanh toán"
                    >
                        {item.balance.toLocaleString('vi-VN')} ₫
                    </button>
                );
            },
            sortable: true,
            sortKey: 'balance' as keyof Student
        },
        { header: 'Trạng thái', accessor: (item: Student) => (
            <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                item.status === PersonStatus.ACTIVE ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
            }`}>
                {item.status === PersonStatus.ACTIVE ? 'Hoạt động' : 'Tạm nghỉ'}
            </span>
        ), sortable: true, sortKey: 'status' as keyof Student },
    ];

    const handleCloseModal = () => {
        setEditingStudent(undefined);
        setModalOpen(false);
        const { returnTo } = location.state || {};
        if (returnTo) {
            navigate(returnTo, { replace: true, state: {} });
        }
    };

    const handleSubmit = async (payload: { student: Student; classIds: string[] }) => {
        const { returnTo } = location.state || {};
        try {
            if (editingStudent) {
                await updateStudent({ 
                    originalId: editingStudent.id, 
                    updatedStudent: payload.student,
                    classIds: payload.classIds 
                });
                toast.success(`Đã cập nhật thông tin học viên ${payload.student.name}`);
                setModalOpen(false);
                setEditingStudent(undefined);
                if (returnTo) {
                    navigate(`/student/${payload.student.id}`, { replace: true, state: {} });
                }
            } else {
                await addStudent(payload);
                toast.success(`Đã thêm học viên mới ${payload.student.name}`);
                handleCloseModal();
            }
        } catch (error: any) {
            toast.error(error.message || 'Đã xảy ra lỗi. Vui lòng thử lại.');
        }
    };

    const handleDeleteClick = (student: Student) => {
        setConfirmModalState({ isOpen: true, student: student });
    };

    const handleConfirmDelete = async () => {
        if (confirmModalState.student) {
            try {
                await deleteStudent(confirmModalState.student.id);
                toast.success(`Đã xoá học viên ${confirmModalState.student.name}`);
            } catch (error) {
                toast.error('Đã xảy ra lỗi khi xóa. Vui lòng thử lại.');
            }
        }
    };


    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <h1 className="text-2xl font-bold">Quản lý Học viên</h1>
                {canManage && (
                    <Button onClick={() => handleOpenModal()}>
                        {ICONS.plus} Thêm học viên
                    </Button>
                )}
            </div>
            <div className="card-base p-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input 
                        type="text" 
                        placeholder="Tìm kiếm học viên (tên, SĐT)..." 
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        className="form-input"
                    />
                    <select
                        value={classFilter}
                        onChange={e => setClassFilter(e.target.value)}
                        className="form-select"
                    >
                        <option value="all">Lọc theo lớp - Tất cả</option>
                        {state.classes.map(c => (
                            <option key={c.id} value={c.id}>{c.name}</option>
                        ))}
                    </select>
                </div>
            </div>

            {/* Desktop Table View */}
            <div className="hidden md:block">
                 <Table<Student>
                    columns={columns}
                    data={paginatedStudents}
                    sortConfig={sortConfig}
                    onSort={handleSort}
                    actions={canManage ? (student) => (
                        <>
                            <button onClick={() => setResetPasswordModalState({ isOpen: true, student: student })} className="text-gray-500 hover:text-gray-800" title="Đặt lại mật khẩu">{React.cloneElement(ICONS.key as React.ReactElement<{ width?: number | string; height?: number | string }>, {width: 20, height: 20})}</button>
                            <button onClick={() => handleOpenModal(student)} className="text-indigo-600 hover:text-indigo-900">{ICONS.edit}</button>
                            <button onClick={() => handleDeleteClick(student)} className="text-red-600 hover:text-red-900">{ICONS.delete}</button>
                        </>
                    ) : undefined}
                />
            </div>

            {/* Mobile Card View */}
            <div className="md:hidden space-y-4">
                {paginatedStudents.map(student => (
                    <div key={student.id} className="card-base p-4">
                        <div className="flex justify-between items-start gap-3">
                            <div className="flex-1">
                                <Link to={`/student/${student.id}`} className="block group">
                                    <h3 className="font-bold text-lg text-primary group-hover:underline">{student.name}</h3>
                                    <p className="text-sm text-gray-500 dark:text-gray-400 font-mono">{student.id}</p>
                                </Link>
                            </div>
                            <span className={`px-2 py-0.5 text-[10px] uppercase tracking-wider font-bold rounded-full shadow-sm ${student.status === PersonStatus.ACTIVE ? 'bg-green-100 text-green-800 dark:bg-green-900/50 dark:text-green-300' : 'bg-red-100 text-red-800 dark:bg-red-900/50 dark:text-red-300'} whitespace-nowrap mt-1`}>
                                {student.status === PersonStatus.ACTIVE ? 'Hoạt động' : 'Tạm nghỉ'}
                            </span>
                        </div>

                        <div className="mt-4 grid grid-cols-2 gap-4 text-sm border-t border-gray-100 dark:border-gray-700 pt-3">
                            <div>
                                <p className="text-xs text-gray-500 dark:text-gray-400">Số điện thoại</p>
                                <p className="font-medium text-gray-800 dark:text-gray-200">{student.phone || 'Chưa có'}</p>
                            </div>
                            <div>
                                <p className="text-xs text-gray-500 dark:text-gray-400">Số dư</p>
                                <p className={`font-bold text-base ${student.balance < 0 ? 'text-red-500' : 'text-green-600'}`}>
                                    {student.balance.toLocaleString('vi-VN')} ₫
                                </p>
                            </div>
                        </div>

                        {canManage && (
                            <div className="mt-3 border-t border-gray-100 dark:border-gray-700 pt-3 flex justify-end items-center space-x-1">
                                {student.balance < 0 && (
                                    <button onClick={() => setPaymentModalState({ isOpen: true, student: student })} className="p-2 rounded-full text-green-600 hover:bg-green-100 dark:hover:bg-green-900/50" title="Ghi nhận thanh toán">
                                        {React.cloneElement(ICONS.finance, {width: 20, height: 20})}
                                    </button>
                                )}
                                <button onClick={() => setResetPasswordModalState({ isOpen: true, student: student })} className="p-2 rounded-full text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-700" title="Đặt lại mật khẩu">
                                    {React.cloneElement(ICONS.key, {width: 20, height: 20})}
                                </button>
                                <button onClick={() => handleOpenModal(student)} className="p-2 rounded-full text-indigo-600 hover:bg-indigo-100 dark:hover:bg-indigo-900/50" title="Sửa">
                                    {ICONS.edit}
                                </button>
                                <button onClick={() => handleDeleteClick(student)} className="p-2 rounded-full text-red-600 hover:bg-red-100 dark:hover:bg-red-900/50" title="Xóa">
                                    {ICONS.delete}
                                </button>
                            </div>
                        )}
                    </div>
                ))}
            </div>

            {paginatedStudents.length > 0 && (
                 <Pagination
                    currentPage={currentPage}
                    totalPages={totalPages}
                    onPageChange={setCurrentPage}
                    totalItems={sortedStudents.length}
                    itemsPerPage={ITEMS_PER_PAGE}
                />
            )}

            <Modal isOpen={isModalOpen} onClose={handleCloseModal} title={editingStudent ? 'Chỉnh sửa Học viên' : 'Thêm Học viên mới'}>
                <StudentForm 
                    student={editingStudent} 
                    onSubmit={handleSubmit} 
                    onCancel={handleCloseModal}
                    allClasses={state.classes}
                    generatedId={generatedStudentId}
                />
            </Modal>
             <ConfirmationModal
                isOpen={confirmModalState.isOpen}
                onClose={() => setConfirmModalState({ isOpen: false, student: null })}
                onConfirm={handleConfirmDelete}
                title="Xác nhận Xóa Học viên"
                message={
                    <p>
                        Bạn có chắc chắn muốn xoá học viên <strong>{confirmModalState.student?.name}</strong>?
                        <br /><br />
                        <span className="font-bold text-red-500">CẢNH BÁO:</span> Toàn bộ dữ liệu học phí, điểm danh và báo cáo của học viên này cũng sẽ bị XOÁ VĨNH VIỄN.
                    </p>
                }
            />
            <ResetPasswordModal
                isOpen={resetPasswordModalState.isOpen}
                onClose={() => setResetPasswordModalState({ isOpen: false, student: null })}
                user={resetPasswordModalState.student}
                role={UserRole.PARENT}
            />
             <PaymentModal
                isOpen={paymentModalState.isOpen}
                onClose={() => setPaymentModalState({ isOpen: false, student: null })}
                student={paymentModalState.student}
            />
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { useData } from '../hooks/useDataContext';
import { Card } from '../components/common/Card';
import { ICONS } from '../constants';
import { LineChart } from '../components/common/LineChart';
import { PieChart } from '../components/common/PieChart';
import { AttendanceStatus, FeeType, TransactionType } from '../types';
import { ReportDetailModal } from '../components/reports/ReportDetailModal';
import { AttendanceReportTab } from '../components/reports/AttendanceReportTab';
import { TransactionHistoryReportTab } from '../components/reports/TransactionHistoryReportTab';

const toLocalDateString = (date: Date): string => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
};

const today = new Date();
const startOfMonth = toLocalDateString(new Date(today.getFullYear(), today.getMonth(), 1));
const endOfMonth = toLocalDateString(new Date(today.getFullYear(), today.getMonth() + 1, 0));

type ReportTab = 'overview' | 'attendance' | 'transactions';

export const ReportsScreen: React.FC = () => {
    const { state } = useData();
    const { students, classes, invoices, income, expenses, attendance, transactions } = state;

    // State cho khoảng thời gian tùy chỉnh
    const [startDate, setStartDate] = useState(startOfMonth);
    const [endDate, setEndDate] = useState(endOfMonth);

    const [classFilter, setClassFilter] = useState('all');
    const [activeTab, setActiveTab] = useState<ReportTab>('overview');
    const [detailModal, setDetailModal] = useState<{
        isOpen: boolean;
        title: string;
        items: { description: string; date: string; amount?: number; type?: 'credit' | 'debit' }[];
    }>({ isOpen: false, title: '', items: [] });

    const filteredStudentIds = useMemo(() => {
        if (classFilter === 'all') {
            return null; // Represents all students
        }
        const selectedClass = classes.find(c => c.id === classFilter);
        return new Set(selectedClass?.studentIds || []);
    }, [classFilter, classes]);

    // Helper: Nhóm dữ liệu cho biểu đồ đường
    const trendAnalytics = useMemo(() => {
        const start = new Date(startDate);
        const end = new Date(endDate);
        const diffTime = Math.abs(end.getTime() - start.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
        const isDaily = diffDays <= 32;

        const dataMap = new Map<string, { revenue: number, expense: number }>();

        // Init map keys
        if (isDaily) {
            let loop = new Date(start);
            while (loop <= end) {
                const key = toLocalDateString(loop);
                dataMap.set(key, { revenue: 0, expense: 0 });
                loop.setDate(loop.getDate() + 1);
            }
        } else {
            let loop = new Date(start);
            // Set to first day of month to avoid skipping months
            loop.setDate(1); 
            while (loop <= end) {
                const key = loop.toISOString().slice(0, 7); // YYYY-MM
                if (!dataMap.has(key)) dataMap.set(key, { revenue: 0, expense: 0 });
                loop.setMonth(loop.getMonth() + 1);
            }
        }

        // Fill Data
        // 1. Revenue from Transactions (Tuition)
        transactions.forEach(t => {
            if (t.date >= startDate && t.date <= endDate) {
                const isPayment = t.type === TransactionType.PAYMENT || t.type === TransactionType.ADJUSTMENT_CREDIT;
                const isNotRefund = !t.description.toLowerCase().includes('hủy hóa đơn');
                const studentIsInClass = filteredStudentIds ? filteredStudentIds.has(t.studentId) : true;

                if (isPayment && isNotRefund && t.amount > 0 && studentIsInClass) {
                    const key = isDaily ? t.date : t.date.slice(0, 7);
                    if (dataMap.has(key)) {
                        dataMap.get(key)!.revenue += t.amount;
                    }
                }
            }
        });

        // 2. Revenue from Other Income (Only if not filtering by class)
        if (!filteredStudentIds) {
            income.forEach(inc => {
                if (inc.date >= startDate && inc.date <= endDate) {
                    const key = isDaily ? inc.date : inc.date.slice(0, 7);
                    if (dataMap.has(key)) {
                        dataMap.get(key)!.revenue += inc.amount;
                    }
                }
            });
        }

        // 3. Expenses (Global)
        expenses.forEach(exp => {
            if (exp.date >= startDate && exp.date <= endDate) {
                const key = isDaily ? exp.date : exp.date.slice(0, 7);
                if (dataMap.has(key)) {
                    dataMap.get(key)!.expense += exp.amount;
                }
            }
        });

        // Convert Map to Array for Chart
        return Array.from(dataMap.entries()).map(([label, values]) => {
            // Format label
            let displayLabel = label;
            if (isDaily) {
                // FIXED: Ignored first element 'y' to prevent TS unused var error
                const [, m, d] = label.split('-');
                displayLabel = `${d}/${m}`;
            } else {
                const [y, m] = label.split('-');
                displayLabel = `T${m}/${y}`;
            }
            return {
                label: displayLabel,
                values: [values.revenue, values.expense]
            };
        });

    }, [transactions, income, expenses, startDate, endDate, filteredStudentIds]);


    // KPIs trong khoảng thời gian đã chọn
    const periodKpiData = useMemo(() => {
        const tuitionFeesCollected = transactions
            .filter(t => {
                const isPayment = t.type === TransactionType.PAYMENT || t.type === TransactionType.ADJUSTMENT_CREDIT;
                const isWithinPeriod = t.date >= startDate && t.date <= endDate;
                const isNotRefund = !t.description.toLowerCase().includes('hủy hóa đơn');
                const studentIsInClass = filteredStudentIds ? filteredStudentIds.has(t.studentId) : true;
                return isPayment && isWithinPeriod && isNotRefund && t.amount > 0 && studentIsInClass;
            })
            .reduce((sum, t) => sum + t.amount, 0);

        const otherIncome = income
            .filter(i => i.date >= startDate && i.date <= endDate)
            .reduce((sum, i) => sum + i.amount, 0);

        // Revenue depends on filter
        const totalRevenue = tuitionFeesCollected + (filteredStudentIds ? 0 : otherIncome);

        // Expenses are always global
        const totalExpense = expenses
            .filter(e => e.date >= startDate && e.date <= endDate)
            .reduce((sum, e) => sum + e.amount, 0);

        let provisionalTuitionFee = 0;

        // Count attendance within the period
        const periodAttendance = attendance.filter(a => 
            a.date >= startDate && a.date <= endDate &&
            (a.status === AttendanceStatus.PRESENT || a.status === AttendanceStatus.LATE)
        );

        const attendanceCountMap = new Map<string, number>();
        periodAttendance.forEach(a => {
            const key = `${a.studentId}-${a.classId}`;
            attendanceCountMap.set(key, (attendanceCountMap.get(key) || 0) + 1);
        });

        const studentsForProvisional = students.filter(s => 
            (s.status === 'ACTIVE') && 
            (filteredStudentIds ? filteredStudentIds.has(s.id) : true)
        );
        const activeStudentIds = new Set(studentsForProvisional.map(s => s.id));

        const classesToCalculate = filteredStudentIds ? classes.filter(c => c.id === classFilter) : classes;

        classesToCalculate.forEach(c => {
            const activeStudentsInClass = c.studentIds.filter(id => activeStudentIds.has(id));

            if (c.fee.type === FeeType.MONTHLY) {
                provisionalTuitionFee += activeStudentsInClass.length * c.fee.amount;
            } else if (c.fee.type === FeeType.PER_SESSION) {
                activeStudentsInClass.forEach(studentId => {
                    const key = `${studentId}-${c.id}`;
                    const attendedSessions = attendanceCountMap.get(key) || 0;
                    provisionalTuitionFee += attendedSessions * c.fee.amount;
                });
            }
        });

        // New Students within period
        const newStudents = students.filter(s => 
            s.createdAt >= startDate && s.createdAt <= endDate &&
            (filteredStudentIds ? filteredStudentIds.has(s.id) : true)
        ).length;

        return {
            totalRevenue,
            totalExpense: totalExpense,
            profit: totalRevenue - totalExpense,
            tuitionFeesCollected,
            provisionalTuitionFee,
            newStudents
        };
    }, [invoices, income, expenses, students, classes, attendance, transactions, startDate, endDate, classFilter, filteredStudentIds]);


    const revenueByClass = useMemo(() => {
        const revenueMap = new Map<string, number>();
        const paidInvoices = invoices.filter(inv => 
            inv.status === 'PAID' && 
            inv.paidDate && inv.paidDate >= startDate && inv.paidDate <= endDate &&
            (filteredStudentIds ? filteredStudentIds.has(inv.studentId) : true)
        );

        paidInvoices.forEach(invoice => {
            const studentClasses = classes.filter(c => (c.studentIds || []).includes(invoice.studentId));
            if (studentClasses.length > 0) {
                const amountPerClass = invoice.amount / studentClasses.length;
                studentClasses.forEach(c => {
                    revenueMap.set(c.name, (revenueMap.get(c.name) || 0) + amountPerClass);
                });
            }
        });

        let finalData = Array.from(revenueMap.entries())
            .map(([label, value]) => ({ label, value, color: '' }))
            .sort((a,b) => b.value - a.value);

        if (classFilter !== 'all') {
            finalData = finalData.filter(d => {
                const cls = classes.find(c => c.id === classFilter);
                return cls?.name === d.label;
            });
        }

        return finalData;

    }, [invoices, classes, startDate, endDate, classFilter, filteredStudentIds]);

    // --- Detail Modal Handlers ---

    const handleShowProvisionalTuitionDetails = () => {
        const items: { description: string; date: string; amount: number; type: 'credit' }[] = [];

        // Logic tương tự periodKpiData nhưng push vào items
        const periodAttendance = attendance.filter(a => 
            a.date >= startDate && a.date <= endDate &&
            (a.status === AttendanceStatus.PRESENT || a.status === AttendanceStatus.LATE)
        );
        const attendanceCountMap = new Map<string, number>();
        periodAttendance.forEach(a => {
            const key = `${a.studentId}-${a.classId}`;
            attendanceCountMap.set(key, (attendanceCountMap.get(key) || 0) + 1);
        });

        const activeStudents = students.filter(s => s.status === 'ACTIVE' && (filteredStudentIds ? filteredStudentIds.has(s.id) : true));
        const studentMap = new Map(students.map(s => [s.id, s.name]));
        const classesToCalculate = filteredStudentIds ? classes.filter(c => c.id === classFilter) : classes;

        classesToCalculate.forEach(c => {
            const activeStudentsInClass = c.studentIds.filter(id => activeStudents.some(s => s.id === id));
            activeStudentsInClass.forEach(studentId => {
                const studentName = studentMap.get(studentId) || 'Không rõ';
                if (c.fee.type === FeeType.MONTHLY) {
                    const key = `${studentId}-${c.id}`;
                    if (attendanceCountMap.has(key)) {
                         items.push({
                            description: `[${c.name}] ${studentName} (HP tháng)`,
                            date: `${startDate} -> ${endDate}`,
                            amount: c.fee.amount,
                            type: 'credit'
                        });
                    }
                } else if (c.fee.type === FeeType.PER_SESSION) {
                    const key = `${studentId}-${c.id}`;
                    const attendedSessions = attendanceCountMap.get(key) || 0;
                    if (attendedSessions > 0) {
                        items.push({
                            description: `[${c.name}] ${studentName} (${attendedSessions} buổi)`,
                            date: `${startDate} -> ${endDate}`,
                            amount: attendedSessions * c.fee.amount,
                            type: 'credit'
                        });
                    }
                }
            });
        });

        setDetailModal({
            isOpen: true,
            title: `Chi tiết Học phí Tạm tính`,
            items: items.sort((a,b) => a.description.localeCompare(b.description))
        });
    };

    const handleShowRevenueDetails = () => {
        const relevantTransactions = transactions
            .filter(t => {
                const isPayment = t.type === TransactionType.PAYMENT || t.type === TransactionType.ADJUSTMENT_CREDIT;
                const isWithin = t.date >= startDate && t.date <= endDate;
                const isNotRefund = !t.description.toLowerCase().includes('hủy hóa đơn');
                const studentIsInClass = filteredStudentIds ? filteredStudentIds.has(t.studentId) : true;
                return isPayment && isWithin && isNotRefund && t.amount > 0 && studentIsInClass;
            });

        const relevantIncome = classFilter === 'all' ? income
            .filter(i => i.date >= startDate && i.date <= endDate) : [];

        // Combine into a raw array to sort by date then by ID to handle same-day order
        const combined = [
            ...relevantTransactions.map(t => ({ ...t, kind: 'transaction' as const })),
            ...relevantIncome.map(i => ({ ...i, kind: 'income' as const }))
        ];

        // Sort descending by date (Newest first). If same date, sort by ID descending (Last entered first).
        combined.sort((a, b) => {
            const timeA = new Date(a.date).getTime();
            const timeB = new Date(b.date).getTime();
            if (timeA !== timeB) return timeB - timeA;
            return b.id.localeCompare(a.id);
        });

        const items = combined.map(item => {
            if (item.kind === 'transaction') {
                const studentName = students.find(s => s.id === item.studentId)?.name || 'Không rõ';
                return {
                    description: `[HP] ${studentName} - ${item.description}`,
                    date: item.date,
                    amount: item.amount,
                    type: 'credit' as const
                };
            } else {
                return {
                    description: `[Thu khác] ${item.description}`,
                    date: item.date,
                    amount: item.amount,
                    type: 'credit' as const
                };
            }
        });

        setDetailModal({ isOpen: true, title: `Chi tiết Doanh thu`, items });
    };

    const handleShowExpenseDetails = () => {
        const items = expenses
            .filter(e => e.date >= startDate && e.date <= endDate)
            .sort((a, b) => {
                const dateA = new Date(a.date).getTime();
                const dateB = new Date(b.date).getTime();
                if (dateA !== dateB) return dateB - dateA;
                return b.id.localeCompare(a.id);
            })
            .map(e => ({
                description: e.description,
                date: e.date,
                amount: e.amount,
                type: 'debit' as const
            }));

        setDetailModal({ isOpen: true, title: `Chi tiết Chi phí`, items });
    };

    const handleShowNewStudentsDetails = () => {
        const items = students
            .filter(s => s.createdAt >= startDate && s.createdAt <= endDate && (filteredStudentIds ? filteredStudentIds.has(s.id) : true))
            .sort((a, b) => {
                const dateA = new Date(a.createdAt).getTime();
                const dateB = new Date(b.createdAt).getTime();
                if (dateA !== dateB) return dateB - dateA;
                return b.id.localeCompare(a.id);
            })
            .map(s => ({
                description: s.name,
                date: s.createdAt,
            }));

        setDetailModal({ isOpen: true, title: `Chi tiết Học viên mới`, items });
    };

    const setPeriod = (type: 'this_month' | 'last_month' | 'this_year') => {
        const now = new Date();
        let start, end;
        switch (type) {
            case 'this_month':
                start = new Date(now.getFullYear(), now.getMonth(), 1);
                end = new Date(now.getFullYear(), now.getMonth() + 1, 0);
                break;
            case 'last_month':
                start = new Date(now.getFullYear(), now.getMonth() - 1, 1);
                end = new Date(now.getFullYear(), now.getMonth(), 0);
                break;
            case 'this_year':
                start = new Date(now.getFullYear(), 0, 1);
                end = new Date(now.getFullYear(), 11, 31);
                break;
        }
        setStartDate(toLocalDateString(start));
        setEndDate(toLocalDateString(end));
    };

    const TabButton: React.FC<{ tabId: ReportTab; children: React.ReactNode }> = ({ tabId, children }) => (
        <button
            onClick={() => setActiveTab(tabId)}
            className={`whitespace-nowrap px-3 sm:px-4 py-2 font-semibold text-sm rounded-md transition-colors ${activeTab === tabId ? 'bg-primary text-white shadow' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
        >
            {children}
        </button>
    );

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <h1 className="text-3xl font-bold">Báo cáo & Phân tích</h1>
            </div>

            {/* Filter Section */}
            <div className="flex flex-col lg:flex-row items-start lg:items-center gap-4 p-4 bg-slate-50 dark:bg-slate-800 rounded-lg border dark:border-slate-700">
                <div className="flex items-center gap-2 flex-wrap">
                    <select value={classFilter} onChange={e => setClassFilter(e.target.value)} className="form-select py-1 px-2 text-sm w-40">
                        <option value="all">Tất cả các lớp</option>
                        {classes.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                    <div className="flex items-center gap-2">
                        <span className="text-sm font-medium whitespace-nowrap">Từ:</span>
                        <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="form-input py-1 px-2 text-sm w-36" />
                    </div>
                    <div className="flex items-center gap-2">
                        <span className="text-sm font-medium whitespace-nowrap">Đến:</span>
                        <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="form-input py-1 px-2 text-sm w-36" />
                    </div>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => setPeriod('this_month')} className="px-3 py-1 text-xs font-medium bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded hover:bg-slate-100 dark:hover:bg-slate-600 transition-colors">Tháng này</button>
                    <button onClick={() => setPeriod('last_month')} className="px-3 py-1 text-xs font-medium bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded hover:bg-slate-100 dark:hover:bg-slate-600 transition-colors">Tháng trước</button>
                    <button onClick={() => setPeriod('this_year')} className="px-3 py-1 text-xs font-medium bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded hover:bg-slate-100 dark:hover:bg-slate-600 transition-colors">Năm nay</button>
                </div>
            </div>

            <div className="border-b border-gray-200 dark:border-gray-700">
                <nav className="flex flex-wrap items-center gap-2 pb-2" aria-label="Tabs">
                    <TabButton tabId="overview">Tổng quan Tài chính</TabButton>
                    <TabButton tabId="attendance">Báo cáo Chuyên cần</TabButton>
                    <TabButton tabId="transactions">Lịch sử Giao dịch</TabButton>
                </nav>
            </div>

            <div>
                {activeTab === 'overview' && (
                    <div className="space-y-6">
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-6">
                            <div className="cursor-pointer transition-transform hover:scale-105" onClick={handleShowProvisionalTuitionDetails}>
                                <Card title={`HP Tạm tính (Kỳ)`} value={`${periodKpiData.provisionalTuitionFee.toLocaleString('vi-VN')} ₫`} icon={ICONS.calendar} color="text-purple-600 dark:text-purple-400" />
                            </div>
                            <div className="cursor-pointer transition-transform hover:scale-105" onClick={handleShowRevenueDetails}>
                                <Card title={`HP Đã thu (Kỳ)`} value={`${periodKpiData.tuitionFeesCollected.toLocaleString('vi-VN')} ₫`} icon={ICONS.checkCircle} color="text-teal-600 dark:text-teal-400" />
                            </div>
                            <div className="cursor-pointer transition-transform hover:scale-105" onClick={handleShowRevenueDetails}>
                                <Card title={`Tổng Doanh thu`} value={`${periodKpiData.totalRevenue.toLocaleString('vi-VN')} ₫`} icon={ICONS.finance} color="text-green-600 dark:text-green-400" />
                            </div>
                            <div className="cursor-pointer transition-transform hover:scale-105" onClick={handleShowExpenseDetails}>
                                <Card title={`Tổng Chi phí`} value={`${periodKpiData.totalExpense.toLocaleString('vi-VN')} ₫`} icon={ICONS.logout} color="text-red-600 dark:text-red-400" />
                            </div>
                            <div className="cursor-pointer transition-transform hover:scale-105" onClick={handleShowRevenueDetails}>
                                <Card title={`Lợi nhuận`} value={`${periodKpiData.profit.toLocaleString('vi-VN')} ₫`} icon={ICONS.reports} color="text-blue-600 dark:text-blue-400" />
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-center">
                            <div className="p-4 bg-gray-50 dark:bg-gray-700 rounded-lg cursor-pointer transition-transform hover:scale-105" onClick={handleShowNewStudentsDetails}>
                                <p className="text-sm font-medium text-gray-500">Học viên mới trong kỳ</p>
                                <p className="text-2xl font-bold text-gray-800 dark:text-white mt-1">{periodKpiData.newStudents}</p>
                            </div>
                        </div>

                        <div className="card-base">
                            <LineChart
                                title={`Xu hướng Tài chính`}
                                data={trendAnalytics}
                                series={[
                                    { name: 'Doanh thu', color: '#10b981' },
                                    { name: 'Chi phí', color: '#ef4444' },
                                ]}
                            />
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                            <div className="card-base">
                                <PieChart title={`Cơ cấu Doanh thu theo Lớp`} data={revenueByClass} />
                            </div>
                        </div>
                    </div>
                )}
                {activeTab === 'attendance' && (
                     <AttendanceReportTab 
                        startDate={startDate}
                        endDate={endDate}
                        classFilter={classFilter}
                    />
                )}
                {activeTab === 'transactions' && (
                    <TransactionHistoryReportTab
                        startDate={startDate}
                        endDate={endDate}
                        classFilter={classFilter}
                    />
                )}
            </div>

            <ReportDetailModal 
                isOpen={detailModal.isOpen}
                onClose={() => setDetailModal({ isOpen: false, title: '', items: [] })}
                title={detailModal.title}
                items={detailModal.items}
            />
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { useData } from '../hooks/useDataContext';
import { Card } from '../components/common/Card';
import { ICONS } from '../constants';
import { LineChart } from '../components/common/LineChart';
import { PieChart } from '../components/common/PieChart';
import { AttendanceStatus, FeeType, TransactionType } from '../types';
import { ReportDetailModal } from '../components/reports/ReportDetailModal';
import { AttendanceReportTab } from '../components/reports/AttendanceReportTab';
import { TransactionHistoryReportTab } from '../components/reports/TransactionHistoryReportTab';

const toLocalDateString = (date: Date): string => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
};

const today = new Date();
const startOfMonth = toLocalDateString(new Date(today.getFullYear(), today.getMonth(), 1));
const endOfMonth = toLocalDateString(new Date(today.getFullYear(), today.getMonth() + 1, 0));

type ReportTab = 'overview' | 'attendance' | 'transactions';

export const ReportsScreen: React.FC = () => {
    const { state } = useData();
    const { students, classes, invoices, income, expenses, attendance, transactions } = state;

    // State cho khoảng thời gian tùy chỉnh
    const [startDate, setStartDate] = useState(startOfMonth);
    const [endDate, setEndDate] = useState(endOfMonth);

    const [classFilter, setClassFilter] = useState('all');
    const [activeTab, setActiveTab] = useState<ReportTab>('overview');
    const [detailModal, setDetailModal] = useState<{
        isOpen: boolean;
        title: string;
        items: { description: string; date: string; amount?: number; type?: 'credit' | 'debit' }[];
    }>({ isOpen: false, title: '', items: [] });

    const filteredStudentIds = useMemo(() => {
        if (classFilter === 'all') {
            return null; // Represents all students
        }
        const selectedClass = classes.find(c => c.id === classFilter);
        return new Set(selectedClass?.studentIds || []);
    }, [classFilter, classes]);

    // Helper: Nhóm dữ liệu cho biểu đồ đường
    const trendAnalytics = useMemo(() => {
        const start = new Date(startDate);
        const end = new Date(endDate);
        const diffTime = Math.abs(end.getTime() - start.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)); 
        const isDaily = diffDays <= 32;

        const dataMap = new Map<string, { revenue: number, expense: number }>();

        // Init map keys
        if (isDaily) {
            let loop = new Date(start);
            while (loop <= end) {
                const key = toLocalDateString(loop);
                dataMap.set(key, { revenue: 0, expense: 0 });
                loop.setDate(loop.getDate() + 1);
            }
        } else {
            let loop = new Date(start);
            // Set to first day of month to avoid skipping months
            loop.setDate(1); 
            while (loop <= end) {
                const key = loop.toISOString().slice(0, 7); // YYYY-MM
                if (!dataMap.has(key)) dataMap.set(key, { revenue: 0, expense: 0 });
                loop.setMonth(loop.getMonth() + 1);
            }
        }

        // Fill Data
        // 1. Revenue from Transactions (Tuition)
        transactions.forEach(t => {
            if (t.date >= startDate && t.date <= endDate) {
                const isPayment = t.type === TransactionType.PAYMENT || t.type === TransactionType.ADJUSTMENT_CREDIT;
                const isNotRefund = !t.description.toLowerCase().includes('hủy hóa đơn');
                const studentIsInClass = filteredStudentIds ? filteredStudentIds.has(t.studentId) : true;

                if (isPayment && isNotRefund && t.amount > 0 && studentIsInClass) {
                    const key = isDaily ? t.date : t.date.slice(0, 7);
                    if (dataMap.has(key)) {
                        dataMap.get(key)!.revenue += t.amount;
                    }
                }
            }
        });

        // 2. Revenue from Other Income (Only if not filtering by class)
        if (!filteredStudentIds) {
            income.forEach(inc => {
                if (inc.date >= startDate && inc.date <= endDate) {
                    const key = isDaily ? inc.date : inc.date.slice(0, 7);
                    if (dataMap.has(key)) {
                        dataMap.get(key)!.revenue += inc.amount;
                    }
                }
            });
        }

        // 3. Expenses (Global)
        expenses.forEach(exp => {
            if (exp.date >= startDate && exp.date <= endDate) {
                const key = isDaily ? exp.date : exp.date.slice(0, 7);
                if (dataMap.has(key)) {
                    dataMap.get(key)!.expense += exp.amount;
                }
            }
        });

        // Convert Map to Array for Chart
        return Array.from(dataMap.entries()).map(([label, values]) => {
            // Format label
            let displayLabel = label;
            if (isDaily) {
                // FIXED: Ignored first element 'y' to prevent TS unused var error
                const [, m, d] = label.split('-');
                displayLabel = `${d}/${m}`;
            } else {
                const [y, m] = label.split('-');
                displayLabel = `T${m}/${y}`;
            }
            return {
                label: displayLabel,
                values: [values.revenue, values.expense]
            };
        });

    }, [transactions, income, expenses, startDate, endDate, filteredStudentIds]);


    // KPIs trong khoảng thời gian đã chọn
    const periodKpiData = useMemo(() => {
        const tuitionFeesCollected = transactions
            .filter(t => {
                const isPayment = t.type === TransactionType.PAYMENT || t.type === TransactionType.ADJUSTMENT_CREDIT;
                const isWithinPeriod = t.date >= startDate && t.date <= endDate;
                const isNotRefund = !t.description.toLowerCase().includes('hủy hóa đơn');
                const studentIsInClass = filteredStudentIds ? filteredStudentIds.has(t.studentId) : true;
                return isPayment && isWithinPeriod && isNotRefund && t.amount > 0 && studentIsInClass;
            })
            .reduce((sum, t) => sum + t.amount, 0);

        const otherIncome = income
            .filter(i => i.date >= startDate && i.date <= endDate)
            .reduce((sum, i) => sum + i.amount, 0);

        // Revenue depends on filter
        const totalRevenue = tuitionFeesCollected + (filteredStudentIds ? 0 : otherIncome);

        // Expenses are always global
        const totalExpense = expenses
            .filter(e => e.date >= startDate && e.date <= endDate)
            .reduce((sum, e) => sum + e.amount, 0);

        let provisionalTuitionFee = 0;

        // Count attendance within the period
        const periodAttendance = attendance.filter(a => 
            a.date >= startDate && a.date <= endDate &&
            (a.status === AttendanceStatus.PRESENT || a.status === AttendanceStatus.LATE)
        );

        const attendanceCountMap = new Map<string, number>();
        periodAttendance.forEach(a => {
            const key = `${a.studentId}-${a.classId}`;
            attendanceCountMap.set(key, (attendanceCountMap.get(key) || 0) + 1);
        });

        const studentsForProvisional = students.filter(s => 
            (s.status === 'ACTIVE') && 
            (filteredStudentIds ? filteredStudentIds.has(s.id) : true)
        );
        const activeStudentIds = new Set(studentsForProvisional.map(s => s.id));

        const classesToCalculate = filteredStudentIds ? classes.filter(c => c.id === classFilter) : classes;

        classesToCalculate.forEach(c => {
            const activeStudentsInClass = c.studentIds.filter(id => activeStudentIds.has(id));

            if (c.fee.type === FeeType.MONTHLY) {
                provisionalTuitionFee += activeStudentsInClass.length * c.fee.amount;
            } else if (c.fee.type === FeeType.PER_SESSION) {
                activeStudentsInClass.forEach(studentId => {
                    const key = `${studentId}-${c.id}`;
                    const attendedSessions = attendanceCountMap.get(key) || 0;
                    provisionalTuitionFee += attendedSessions * c.fee.amount;
                });
            }
        });

        // New Students within period
        const newStudents = students.filter(s => 
            s.createdAt >= startDate && s.createdAt <= endDate &&
            (filteredStudentIds ? filteredStudentIds.has(s.id) : true)
        ).length;

        return {
            totalRevenue,
            totalExpense: totalExpense,
            profit: totalRevenue - totalExpense,
            tuitionFeesCollected,
            provisionalTuitionFee,
            newStudents
        };
    }, [invoices, income, expenses, students, classes, attendance, transactions, startDate, endDate, classFilter, filteredStudentIds]);


    const revenueByClass = useMemo(() => {
        const revenueMap = new Map<string, number>();
        const paidInvoices = invoices.filter(inv => 
            inv.status === 'PAID' && 
            inv.paidDate && inv.paidDate >= startDate && inv.paidDate <= endDate &&
            (filteredStudentIds ? filteredStudentIds.has(inv.studentId) : true)
        );

        paidInvoices.forEach(invoice => {
            const studentClasses = classes.filter(c => (c.studentIds || []).includes(invoice.studentId));
            if (studentClasses.length > 0) {
                const amountPerClass = invoice.amount / studentClasses.length;
                studentClasses.forEach(c => {
                    revenueMap.set(c.name, (revenueMap.get(c.name) || 0) + amountPerClass);
                });
            }
        });

        let finalData = Array.from(revenueMap.entries())
            .map(([label, value]) => ({ label, value, color: '' }))
            .sort((a,b) => b.value - a.value);

        if (classFilter !== 'all') {
            finalData = finalData.filter(d => {
                const cls = classes.find(c => c.id === classFilter);
                return cls?.name === d.label;
            });
        }

        return finalData;

    }, [invoices, classes, startDate, endDate, classFilter, filteredStudentIds]);

    // --- Detail Modal Handlers ---

    const handleShowProvisionalTuitionDetails = () => {
        const items: { description: string; date: string; amount: number; type: 'credit' }[] = [];

        // Logic tương tự periodKpiData nhưng push vào items
        const periodAttendance = attendance.filter(a => 
            a.date >= startDate && a.date <= endDate &&
            (a.status === AttendanceStatus.PRESENT || a.status === AttendanceStatus.LATE)
        );
        const attendanceCountMap = new Map<string, number>();
        periodAttendance.forEach(a => {
            const key = `${a.studentId}-${a.classId}`;
            attendanceCountMap.set(key, (attendanceCountMap.get(key) || 0) + 1);
        });

        const activeStudents = students.filter(s => s.status === 'ACTIVE' && (filteredStudentIds ? filteredStudentIds.has(s.id) : true));
        const studentMap = new Map(students.map(s => [s.id, s.name]));
        const classesToCalculate = filteredStudentIds ? classes.filter(c => c.id === classFilter) : classes;

        classesToCalculate.forEach(c => {
            const activeStudentsInClass = c.studentIds.filter(id => activeStudents.some(s => s.id === id));
            activeStudentsInClass.forEach(studentId => {
                const studentName = studentMap.get(studentId) || 'Không rõ';
                if (c.fee.type === FeeType.MONTHLY) {
                    const key = `${studentId}-${c.id}`;
                    if (attendanceCountMap.has(key)) {
                         items.push({
                            description: `[${c.name}] ${studentName} (HP tháng)`,
                            date: `${startDate} -> ${endDate}`,
                            amount: c.fee.amount,
                            type: 'credit'
                        });
                    }
                } else if (c.fee.type === FeeType.PER_SESSION) {
                    const key = `${studentId}-${c.id}`;
                    const attendedSessions = attendanceCountMap.get(key) || 0;
                    if (attendedSessions > 0) {
                        items.push({
                            description: `[${c.name}] ${studentName} (${attendedSessions} buổi)`,
                            date: `${startDate} -> ${endDate}`,
                            amount: attendedSessions * c.fee.amount,
                            type: 'credit'
                        });
                    }
                }
            });
        });

        setDetailModal({
            isOpen: true,
            title: `Chi tiết Học phí Tạm tính`,
            items: items.sort((a,b) => a.description.localeCompare(b.description))
        });
    };

    const handleShowRevenueDetails = () => {
        const relevantTransactions = transactions
            .filter(t => {
                const isPayment = t.type === TransactionType.PAYMENT || t.type === TransactionType.ADJUSTMENT_CREDIT;
                const isWithin = t.date >= startDate && t.date <= endDate;
                const isNotRefund = !t.description.toLowerCase().includes('hủy hóa đơn');
                const studentIsInClass = filteredStudentIds ? filteredStudentIds.has(t.studentId) : true;
                return isPayment && isWithin && isNotRefund && t.amount > 0 && studentIsInClass;
            });

        const relevantIncome = classFilter === 'all' ? income
            .filter(i => i.date >= startDate && i.date <= endDate) : [];

        // Combine into a raw array to sort by date then by ID to handle same-day order
        const combined = [
            ...relevantTransactions.map(t => ({ ...t, kind: 'transaction' as const })),
            ...relevantIncome.map(i => ({ ...i, kind: 'income' as const }))
        ];

        // Sort descending by date (Newest first). If same date, sort by ID descending (Last entered first).
        combined.sort((a, b) => {
            const timeA = new Date(a.date).getTime();
            const timeB = new Date(b.date).getTime();
            if (timeA !== timeB) return timeB - timeA;
            return b.id.localeCompare(a.id);
        });

        const items = combined.map(item => {
            if (item.kind === 'transaction') {
                const studentName = students.find(s => s.id === item.studentId)?.name || 'Không rõ';
                return {
                    description: `[HP] ${studentName} - ${item.description}`,
                    date: item.date,
                    amount: item.amount,
                    type: 'credit' as const
                };
            } else {
                return {
                    description: `[Thu khác] ${item.description}`,
                    date: item.date,
                    amount: item.amount,
                    type: 'credit' as const
                };
            }
        });

        setDetailModal({ isOpen: true, title: `Chi tiết Doanh thu`, items });
    };

    const handleShowExpenseDetails = () => {
        const items = expenses
            .filter(e => e.date >= startDate && e.date <= endDate)
            .sort((a, b) => {
                const dateA = new Date(a.date).getTime();
                const dateB = new Date(b.date).getTime();
                if (dateA !== dateB) return dateB - dateA;
                return b.id.localeCompare(a.id);
            })
            .map(e => ({
                description: e.description,
                date: e.date,
                amount: e.amount,
                type: 'debit' as const
            }));

        setDetailModal({ isOpen: true, title: `Chi tiết Chi phí`, items });
    };

    const handleShowNewStudentsDetails = () => {
        const items = students
            .filter(s => s.createdAt >= startDate && s.createdAt <= endDate && (filteredStudentIds ? filteredStudentIds.has(s.id) : true))
            .sort((a, b) => {
                const dateA = new Date(a.createdAt).getTime();
                const dateB = new Date(b.createdAt).getTime();
                if (dateA !== dateB) return dateB - dateA;
                return b.id.localeCompare(a.id);
            })
            .map(s => ({
                description: s.name,
                date: s.createdAt,
            }));

        setDetailModal({ isOpen: true, title: `Chi tiết Học viên mới`, items });
    };

    const setPeriod = (type: 'this_month' | 'last_month' | 'this_year') => {
        const now = new Date();
        let start, end;
        switch (type) {
            case 'this_month':
                start = new Date(now.getFullYear(), now.getMonth(), 1);
                end = new Date(now.getFullYear(), now.getMonth() + 1, 0);
                break;
            case 'last_month':
                start = new Date(now.getFullYear(), now.getMonth() - 1, 1);
                end = new Date(now.getFullYear(), now.getMonth(), 0);
                break;
            case 'this_year':
                start = new Date(now.getFullYear(), 0, 1);
                end = new Date(now.getFullYear(), 11, 31);
                break;
        }
        setStartDate(toLocalDateString(start));
        setEndDate(toLocalDateString(end));
    };

    const TabButton: React.FC<{ tabId: ReportTab; children: React.ReactNode }> = ({ tabId, children }) => (
        <button
            onClick={() => setActiveTab(tabId)}
            className={`whitespace-nowrap px-3 sm:px-4 py-2 font-semibold text-sm rounded-md transition-colors ${activeTab === tabId ? 'bg-primary text-white shadow' : 'text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'}`}
        >
            {children}
        </button>
    );

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <h1 className="text-3xl font-bold">Báo cáo & Phân tích</h1>
            </div>

            {/* Filter Section */}
            <div className="flex flex-col lg:flex-row items-start lg:items-center gap-4 p-4 bg-slate-50 dark:bg-slate-800 rounded-lg border dark:border-slate-700">
                <div className="flex items-center gap-2 flex-wrap">
                    <select value={classFilter} onChange={e => setClassFilter(e.target.value)} className="form-select py-1 px-2 text-sm w-40">
                        <option value="all">Tất cả các lớp</option>
                        {classes.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                    </select>
                    <div className="flex items-center gap-2">
                        <span className="text-sm font-medium whitespace-nowrap">Từ:</span>
                        <input type="date" value={startDate} onChange={e => setStartDate(e.target.value)} className="form-input py-1 px-2 text-sm w-36" />
                    </div>
                    <div className="flex items-center gap-2">
                        <span className="text-sm font-medium whitespace-nowrap">Đến:</span>
                        <input type="date" value={endDate} onChange={e => setEndDate(e.target.value)} className="form-input py-1 px-2 text-sm w-36" />
                    </div>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => setPeriod('this_month')} className="px-3 py-1 text-xs font-medium bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded hover:bg-slate-100 dark:hover:bg-slate-600 transition-colors">Tháng này</button>
                    <button onClick={() => setPeriod('last_month')} className="px-3 py-1 text-xs font-medium bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded hover:bg-slate-100 dark:hover:bg-slate-600 transition-colors">Tháng trước</button>
                    <button onClick={() => setPeriod('this_year')} className="px-3 py-1 text-xs font-medium bg-white dark:bg-slate-700 border border-slate-300 dark:border-slate-600 rounded hover:bg-slate-100 dark:hover:bg-slate-600 transition-colors">Năm nay</button>
                </div>
            </div>

            <div className="border-b border-gray-200 dark:border-gray-700">
                <nav className="flex flex-wrap items-center gap-2 pb-2" aria-label="Tabs">
                    <TabButton tabId="overview">Tổng quan Tài chính</TabButton>
                    <TabButton tabId="attendance">Báo cáo Chuyên cần</TabButton>
                    <TabButton tabId="transactions">Lịch sử Giao dịch</TabButton>
                </nav>
            </div>

            <div>
                {activeTab === 'overview' && (
                    <div className="space-y-6">
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-6">
                            <div className="cursor-pointer transition-transform hover:scale-105" onClick={handleShowProvisionalTuitionDetails}>
                                <Card title={`HP Tạm tính (Kỳ)`} value={`${periodKpiData.provisionalTuitionFee.toLocaleString('vi-VN')} ₫`} icon={ICONS.calendar} color="text-purple-600 dark:text-purple-400" />
                            </div>
                            <div className="cursor-pointer transition-transform hover:scale-105" onClick={handleShowRevenueDetails}>
                                <Card title={`HP Đã thu (Kỳ)`} value={`${periodKpiData.tuitionFeesCollected.toLocaleString('vi-VN')} ₫`} icon={ICONS.checkCircle} color="text-teal-600 dark:text-teal-400" />
                            </div>
                            <div className="cursor-pointer transition-transform hover:scale-105" onClick={handleShowRevenueDetails}>
                                <Card title={`Tổng Doanh thu`} value={`${periodKpiData.totalRevenue.toLocaleString('vi-VN')} ₫`} icon={ICONS.finance} color="text-green-600 dark:text-green-400" />
                            </div>
                            <div className="cursor-pointer transition-transform hover:scale-105" onClick={handleShowExpenseDetails}>
                                <Card title={`Tổng Chi phí`} value={`${periodKpiData.totalExpense.toLocaleString('vi-VN')} ₫`} icon={ICONS.logout} color="text-red-600 dark:text-red-400" />
                            </div>
                            <div className="cursor-pointer transition-transform hover:scale-105" onClick={handleShowRevenueDetails}>
                                <Card title={`Lợi nhuận`} value={`${periodKpiData.profit.toLocaleString('vi-VN')} ₫`} icon={ICONS.reports} color="text-blue-600 dark:text-blue-400" />
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-center">
                            <div className="p-4 bg-gray-50 dark:bg-gray-700 rounded-lg cursor-pointer transition-transform hover:scale-105" onClick={handleShowNewStudentsDetails}>
                                <p className="text-sm font-medium text-gray-500">Học viên mới trong kỳ</p>
                                <p className="text-2xl font-bold text-gray-800 dark:text-white mt-1">{periodKpiData.newStudents}</p>
                            </div>
                        </div>

                        <div className="card-base">
                            <LineChart
                                title={`Xu hướng Tài chính`}
                                data={trendAnalytics}
                                series={[
                                    { name: 'Doanh thu', color: '#10b981' },
                                    { name: 'Chi phí', color: '#ef4444' },
                                ]}
                            />
                        </div>

                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                            <div className="card-base">
                                <PieChart title={`Cơ cấu Doanh thu theo Lớp`} data={revenueByClass} />
                            </div>
                        </div>
                    </div>
                )}
                {activeTab === 'attendance' && (
                     <AttendanceReportTab 
                        startDate={startDate}
                        endDate={endDate}
                        classFilter={classFilter}
                    />
                )}
                {activeTab === 'transactions' && (
                    <TransactionHistoryReportTab
                        startDate={startDate}
                        endDate={endDate}
                        classFilter={classFilter}
                    />
                )}
            </div>

            <ReportDetailModal 
                isOpen={detailModal.isOpen}
                onClose={() => setDetailModal({ isOpen: false, title: '', items: [] })}
                title={detailModal.title}
                items={detailModal.items}
            />
        </div>
    );
};
